func main() {
	file, err := os.Open("large_file.txt")
	if err != nil {
		fmt.Println(err)
		return
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	buffer := make([]byte, 1024)

	for {
		n, err := reader.Read(buffer)
		if err != nil && err != io.EOF {
			fmt.Println(err)
			return
		}

		fmt.Print(string(buffer[:n]))

		if err == io.EOF {
			break
		}
	}
}

