	results := make(chan int, 5) // increased buffer size to 5
	var wg sync.WaitGroup

	for w := 1; w <= 3; w++ {
		wg.Add(1)
		go worker(w, jobs, results, &wg)
	}

	for j := 1; j <= 5; j++ {
		jobs <- j
	}
	close(jobs)

	wg.Wait() // main goroutine waits for all workers to finish

	for a := 1; a <= 5; a++ {
		<-results
	}
}

