import Foundation

class SecureBuffer {
    private var buffer: [UInt8] = []

    func addData(_ data: [UInt8]) {
        let availableSpace = 1024 - buffer.count
        let dataToAdd = Array(data.prefix(availableSpace))
        buffer.append(contentsOf: dataToAdd)
    }
}

