func (c *Counter) Increment(wg *sync.WaitGroup) {
	c.Lock()
	defer c.Unlock()
	c.value += 1000
	wg.Done()
}

func main() {
	var wg sync.WaitGroup
	counter := &Counter{}
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go counter.Increment(&wg)
	}
	wg.Wait()
	fmt.Println("Counter value:", counter.value)
}

