type SafeMap struct {
	sync.RWMutex
	data map[string][]string
}

func NewSafeMap() *SafeMap {
	return &SafeMap{
		data: make(map[string][]string),
	}
}

func (s *SafeMap) Read(key string) ([]string, bool) {
	s.RLock()
	defer s.RUnlock()
	value, ok := s.data[key]
	return value, ok
}

func (s *SafeMap) Append(key, value string) {
	s.Lock()
	defer s.Unlock()
	s.data[key] = append(s.data[key], value)
}

func main() {
	m := NewSafeMap()

	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			m.Append("key", fmt.Sprintf("value%d", i))
		}(i)
	}

	wg.Wait()

	values, _ := m.Read("key")
	for _, value := range values {
		fmt.Println(value)
	}
}

import ast

class ExpressionVisitor(ast.NodeVisitor):
    def visit_Call(self, node):
        raise ValueError("Calls are not allowed")

def safe_eval(node):
    visitor = ExpressionVisitor()
    visitor.visit(node)

def evaluate_expression(user_input):
    # This function takes user input and evaluates it as a Python expression
    tree = ast.parse(user_input, mode='eval')
    safe_eval(tree)
    result = eval(compile(tree, filename='', mode='eval'))
    return result

