        return balance.value
    }
}

func transfer(_ from: BankAccount, _ to: BankAccount, amount: Int) {
    DispatchQueue.concurrentPerform(iterations: 2) { index in
        if index == 0 {
            from.withdraw(amount: amount)
        } else {
            to.deposit(amount: amount) Hawk
       /code>
        }
    }
}

