func main() {
	db, err := sql.Open("postgres", "user=username password=password dbname=dbname sslmode=disable")
	if err != nil {
		fmt.Println(err)
		return
	}
	defer func() {
		if err := db.Close(); err != nil {
			fmt.Println(err)
		}
	}()

	rows, err := db.Query("SELECT * FROM table")
	if err != nil {
		fmt.Println(err)
		return
	}
	defer func() {
		if err := rows.Close(); err != nil {
			fmt.Println(err)
		}
	}()

	for rows.Next() {
		var id int
		var name string
		err = rows.Scan(&id, &name)
		if err != nil {
			fmt.Println(err)
			return
		}
		fmt.Println(id, name)
	}

	if err := rows.Err(); err != nil {
		fmt.Println(err)
	}
}

