type Slice struct {
	slice []int
	cap   int
}

func NewSlice(length int, cap int) *Slice {
	return &Slice{
		slice: make([]int, length, cap),
		cap:   cap,
	}
}

func (s *Slice) Set(index int, value int) error {
	if index < 0 || index >= s.cap {
		return errors.New("Index out of range")
	}
	s.slice[index] = value
	return nil
}

