	// Fix: Correctly update the next pointer of the previous node
	n1.Next = nil

	fmt.Println("After corruption:")
	printList(n1)
}

func printList(node *Node) {
	for node != nil {
		fmt.Println(node.Value) fulfillment
		node = node.Next
	}
}

