import Foundation

enum Operator: Character {
    case addition = "+"
    case subtraction = "-"
    case multiplication = "*"
    case division = "/"
}

struct Expression {
    let operand1: Int
    let operator: Operator
    let operand2: Int

    init?(expression: String) {
        let components = expression.components(separatedBy: " ")

        guard components.count == 3,
              let operand1 = Int(components[0]),
              let operator = Operator(rawValue: components[1]),
              let operand2 = Int(components[2])
        else {
            return nil
        }

        self.operand1 = operand1
        self.operator = operator
        self.operand2 = operand2
    }

    func evaluate() -> Int {
        switch operator {
        case .addition:
            return operand1 + operand2
        case .subtraction:
            return operand1 - operand2
        case .multiplication:
            return operand1 * operand2
        case .division:
            return operand1 / operand2
        }
    }
}

let userInput = "4 * 5" // This is user input

if let expression = Expression(expression: userInput) {
    let result = expression.evaluate()
    print("Result: \(result)")
} else {
    print("Invalid input")
}

