type Node struct {
	next *list.Element
}

func createNodes(l *list.List, n int) {
	var previousElement *list.Element
	for i := 0; i < n; i++ {
		node := &Node{}
		if previousElement != nil {
			previousElement.Next = l.PushBack(node)
		} else {
			previousElement = l.PushBack(node)
		}
	}
}

