	writer := bufio.NewWriter(file)
	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			_, err := writer.WriteString(fmt.Sprintf("Goroutine %d\n", i))
			if err != nil {
				fmt.Println(err)
