class RestrictedPythonEnvironment(object):
    def __init__(self):
        self.allowed_names = {
            '__builtins__': __builtins__,
            # Add any allowed names here
        }

    def eval(self, expression):
        code = compile(expression, '<string>', 'eval')
        for name in code.co_names:
