func replaceAt(s string, offset int, new string) string {
	totalSize := len(s) + len(new) - 1
	if totalSize > utf8.UTFMax {
		offset++
	}
	out := s[:offset] + new + s[offset+1:]
	return out
}

func main() {
	input := "Hello, 世界"
	var output string
	for i, ch := range input {
		if ch == 'l' {
			output = replaceAt(input, i, "r")
			input = output
		}
	}
	fmt.Println(output)
}

