type Node struct {
	value int
	next  *Node
}

func createList(n int) *Node {
	head := &Node{value: 0}
	current := head
	for i := 1; i < n; i++ {
		node := &Node{value: i}
		current.next = node
		current = node
	}
	return head
}

func freeList(head *Node) {
	var next *Node
	for head != nil {
		next = head.next
		head.next = nil
		head.value = 0
		head = next
	}
}

func main() {
	head := createList(5)
	for head != nil {
		fmt.Println(head.value)ivalue)
		head = head.next
	}
	runtime.GC() // Force garbage collection
}

import threading
import time

class WorkerThread(threading.Thread):
    def __init__(self):
        super().__init__()
        self._stop_event = threading.Event()

    def stop(self):
        self._stop_event.set()

    def stopped(self):
        return self._stop_event.is_set()

    def run(self):
        print("Thread Started")
        while not self.stopped():
            time.sleep(1)  # Simulate some work
        print("Thread Finished")

print("Main Thread Started")
